    baseRate: 150,
    highSeasonAdd: 60,
    extraFee: (guests) => (guests > 2 ? 25 : 0),
  },
  villa: {
    minimumStay: 3,
    maxNights: 28,
    maxGuests: 8,
    baseRate: 300,
    highSeasonAdd: 120,
    extraFee: () => 500,
  },
};

const isInteger = (value: unknown): value is number => Number.isInteger(value);
const isSeason = (value: unknown): boolean => value === "low" || value === "high";
const isHighSeason = (value: unknown): boolean => value === "high";

/** True when a guest qualifies for a 10% discount and a flexible policy. */
function qualifies(loyaltyYears: number, coupon: unknown): boolean {
  return loyaltyYears >= LOYALTY_DISCOUNT_AFTER_YEARS || coupon === "VIP";
}

function quoteResult(
  category: string,
  nights: number,
  total: number,
  policy: string
): QuoteResult {
  return { ok: true, total, policy, line: `${category}:${nights}n:${total}:${policy}` };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyaltyYears = req.loyaltyYears as number;

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }
  const category = req.category as string;

  if (!isInteger(req.nights) || (req.nights as number) < MIN_NIGHTS || (req.nights as number) > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  const nights = req.nights as number;
  if (nights < config.minimumStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  if (!isInteger(req.guests) || (req.guests as number) < MIN_GUESTS || (req.guests as number) > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (!isSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  const guests = req.guests as number;

  const eligible = qualifies(loyaltyYears, req.coupon);

  let total = config.baseRate * nights;
  if (isHighSeason(req.season)) {
    total += config.highSeasonAdd * nights;
  }
  if (eligible) {
    total -= Math.floor(total / DISCOUNT_FACTOR);
  }
  total += config.extraFee(guests);

  return quoteResult(category, nights, total, eligible ? "flex" : "strict");
}

