function strip(ts) {
  return ts
    .replace(/export\s+interface\s+\w+\s*\{[\s\S]*?\n\}/g, '')
    .replace(/export\s+function\s+(quoteBooking)(\s*\([\s\S]*?\)\s*:\s*QuoteResult)\s*{/, 'function $1(raw){')
    .replace(/:\s*(unknown|number|string|boolean|Readonly<Record<string, CategoryConfig>>|CategoryConfig)\b/g, '')
    .replace(/\busize\s*\(([^)]*)\)/g, 'isInteger($1)')
    .replace(/\?\./g,'.')
    .replace(/readonly\s+/g,'')
    ;
}
