const fs = require('fs');

function exec(src) {
  const Module = require('module');
  const m = new Module('test');
  m._compile(src, 'test');
  return m.exports.quoteBooking;
}

const origSrc = fs.readFileSync('/tmp/orig_quote_booking.ts', 'utf8');
const newSrc = fs.readFileSync('/tmp/new_quote_booking.ts', 'utf8');
// new file already has new version written; sync
const fs2 = fs;
const written = fs2.readFileSync('/tmp/eval-work-WMhOFu/quote_booking.ts','utf8');

const orig = exec(origSrc);
const destcompile = written === newSrc ? newSrc : fs2.readFileSync('/tmp/eval-work-WMhOFu/quote_booking.ts','utf8');
const neu = exec(destcompile);

// Build test cases across all categories and edge values
const loyaltyVals = [-1,0,1,2,2.5,3,4,100];
const nightVals = [0,1,2,2.5,3,4,14,15,21,22,28,29];
const guestVals = [0,1,2,3,4,5,8,9,10];
const seasonVals = ['low','high','mid',undefined,5];
const couponVals = ['VIP','vip',undefined,'GOLD'];

let mismatches = 0, count = 0;
for (const cat of ['standard','suite','villa','penthouse',undefined,5]) {
  for (const l of loyaltyVals) for (const n of nightVals) for (const g of guestVals)
    for (const s of seasonVals) for (const c of couponVals) {
      const raw = { category: cat, loyaltyYears: l, nights: n, guests: g, season: s, coupon: c };
      const a = orig(raw), b = neu(raw);
      count++;
      if (JSON.stringify(a) !== JSON.stringify(b)) {
        mismatches++;
        if (mismatches <= 30) console.log('MISMATCH', JSON.stringify(raw), 'orig=', JSON.stringify(a), 'new=', JSON.stringify(b));
      }
    }
}
// Also test general object shapes / missing keys
const weird = [
  null, 5, 'x', {}, [], {loyaltyYears:'3'}, {category:'standard'}, {category:'standard',loyaltyYears:0},
  {category:'standard',loyaltyYears:0,nights:1}, {category:'villa',loyaltyYears:0,nights:1,guests:1,season:'low'},
  {category:'villa',loyaltyYears:0,nights:3,guests:1,season:'low'},
];
for (const raw of weird) {
  const a = orig(raw), b = neu(raw);
  count++;
