/**
 * Per-category configuration. All of the numeric rules (base nightly rate,
 * high-season surcharge, maximum nights/guests, minimum stay and any extra
 * one-off fee) live in one table instead of being scattered across three
 * duplicated branches.
 */


const MIN_NIGHTS = 1;
const MIN_GUESTS = 1;
const LOYALTY_DISCOUNT_AFTER_YEARS = 3;
const DISCOUNT_FACTOR = 10;

const CATEGORIES: {} = {
  standard: {
    minimumStay: 1,
    maxNights: 14,
    maxGuests: 2,
    baseRate: 80,
    highSeasonAdd: 30,
    extraFee: () => 0,
  },
  suite: {
    minimumStay: 1,
    maxNights: 21,
    maxGuests: 4,
    baseRate: 150,
    highSeasonAdd: 60,
    extraFee: (guests) => (guests > 2 ? 25 : 0),
  },
  villa: {
    minimumStay: 3,
    maxNights: 28,
    maxGuests: 8,
    baseRate: 300,
    highSeasonAdd: 120,
    extraFee: () => 500,
  },
};

const isInteger = (value): value is number => Number.Number.isInteger(value);
const isSeason = (value) => value === "low" || value === "high";
const isHighSeason = (value) => value === "high";

/** True when a guest qualifies for a 10% discount and a flexible policy. */
function qualifies(loyaltyYears, coupon) {
  return loyaltyYears >= LOYALTY_DISCOUNT_AFTER_YEARS || coupon === "VIP";
}

function quoteResult(
  category,
  nights,
  total,
  policy
): QuoteResult {
  return { ok: true, total, policy, line: `${category}:${nights}n:${total}:${policy}` };
}

