function quoteBooking(raw){
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyaltyYears = req.loyaltyYears as number;

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }
  const category = req.category as string;

  if (!Number.isInteger(req.nights) || (req.nights as number) < MIN_NIGHTS || (req.nights as number) > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  const nights = req.nights as number;
  if (nights < config.minimumStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  if (!Number.isInteger(req.guests) || (req.guests as number) < MIN_GUESTS || (req.guests as number) > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (!isSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  const guests = req.guests as number;

  const eligible = qualifies(loyaltyYears, req.coupon);

  let total = config.baseRate * nights;
  if (isHighSeason(req.season)) {
    total += config.highSeasonAdd * nights;
  }
  if (eligible) {
    total -= Math.floor(total / DISCOUNT_FACTOR);
  }
  total += config.extraFee(guests);

  return quoteResult(category, nights, total, eligible ? "flex" : "strict");
}

