];
for (const raw of weird) {
  const a = orig(raw), b = neu(raw); count++;
  if (JSON.stringify(a) !== JSON.stringify(b)) { mismatches++; console.log('MISMATCH', JSON.stringify(raw), a, b); }
}
console.log('count', count, 'mismatches', mismatches);
