cd /tmp && cat > /tmp/strip3.js << 'STRIPEOF'
function strip(ts) {
  let s = ts;
  s = s.replace(/export\s*interface\s+\w+\s*\{[\s\S]*?\n\}/g, '');
  s = s.replace(/interface\s+CategoryConfig[\s\S]*?\n\}/g, '');
  s = s.replace(/export\s+function\s+quoteBooking[\s\S]*?\)\s*:\s*QuoteResult\s*\{/, 'function quoteBooking(raw){');
  s = s.split('\n').map(line => {
    // remove single-line ' as Type' casts
    line = line.replace(/\s+as\s+Record<string,\s*unknown>/g, '');
    line = line.replace(/\s+as\s+(?:number|string|boolean)/g, '');
    // remove ': Type' in various spots but keep object/map/array/ternary/template colons
    line = line.replace(/\bvalue\s+is\s+number\b/g, 'boolean');
    line = line.replace(/:(\s*)(?:number|string|boolean|unknown|QuoteResult)\b/g, '');
    line = line.replace(/:(\s*)CategoryConfig\b/g, '');
    line = line.replace(/const\s+CATEGORIES\s*:\s*[^{]*?=/g, 'const CATEGORIES =');
    line = line.replace(/readonly\s+/g, '');
    return line;
  }).join('\n');
  s = s.replace(/\(value\):\s*boolean\s*=>/g, '(value) =>'); // after bool-> boolean
  s = s.replace(/\(value\):\s*boolean\s*=>/g, '(value) =>');
  s = s.replace(/\((\w+):\s*number\)\s*=>/g, '($1) =>');
  s = s.replace(/\bisInteger\s*\(/g, 'Number.isInteger(');
  s = s.replace(/\bNumber\.Number\.isInteger/g, 'Number.isInteger');
  s = s.replace(/\)\s*:\s*QuoteResult/g, ')');
  return s;
}
module.exports = strip;
